        { "text", text = "|cOXP_FRIENDLY_Archmage Xylem|r again" },
        { "text", text = "Back to |cOXP_FRIENDLY_Sanath Lim-yo|r and up to the tower." },
        { "goto", x = 29.25, y = 40.21, zone = "1447" },
        { "turnin", quest = 8252, text = "Turn in The Siren's Coral" },
        { "target", name = "Archmage Xylem" },
        { "goto", x = 29.25, y = 40.21, zone = "1447" },
        { "accept", quest = 8253, text = "Accept Destroy Morphaz" },
        { "target", name = "Archmage Xylem" },
      },
      { only = "Mage", source = "polestar:forever/class/mage/destroy-morphaz",
        { "text", text = "Morphaz" },
        { "text", text = "The Temple of Atal'Hakkar, the Sunken Temple, lies in the Pool of Tears: climb the steps into the sunken building, swim down through it and follow the passage down to the portal. A group of five, level 50-54. Morphaz is not waiting when you arrive. First kill the six troll guardians (elites of 50-52) on the platforms around the upper ring; that opens the way down (the left-hand ramp from the entrance) to |cOXP_FRIENDLY_Jammal'an the Prophet|r and |cOXP_FRIENDLY_Ogom the Wretched|r in the Pit of Sacrifice. Once Jammal'an dies, two green drakes, Weaver and Dreamscythe, come out and patrol the pit: pull them one at a time. When both are dead, Morphaz (level 52 elite, Acid Breath and Wing Flap) and Hazzas appear together and cannot be split, so fight both. The shard always drops. Hunters, Priests and Rogues of 50 need Morphaz too: a group of them shares one clear." },
        { "goto", x = 69.9, y = 53.6, zone = "1435" },
        { "complete", obj = 1, quest = 8253, text = "Arcane Shard: 1 (|cOXP_LOOT_Arcane Shard|r: Morphaz)" },
      },
      { only = "Mage", source = "polestar:forever/class/mage/destroy-morphaz",
        { "text", text = "The |cOXP_LOOT_Arcane Shard|r" },
        { "text", text = "Back to Azshara, |cOXP_FRIENDLY_Sanath Lim-yo|r and the tower. Look at the reward window before you hand in: Classic offered the |cOXP_LOOT_Arcane Crystal Pendant|r, the |cOXP_LOOT_Fire Ruby|r or the |cOXP_LOOT_Glacial Spike|r, and Forever's notes say the choice may be gone." },
        { "goto", x = 29.25, y = 40.21, zone = "1447" },
        { "turnin", quest = 8253, text = "Turn in Destroy Morphaz" },
        { "target", name = "Archmage Xylem" },
      },
      { only = "Human Paladin", source = "polestar:forever/class/paladin/holy-mightstone",
        { "text", text = "Class quest: {item:20620}" },
        { "text", text = "|cOXP_FRIENDLY_Lord Grayson Shadowbreaker|r" },
        { "text", text = "At 50 |cOXP_FRIENDLY_Lord Grayson Shadowbreaker|r, the paladin trainer in the Cathedral of Light, sends you to Chillwind Camp in the Western Plaguelands. |cOXP_FRIENDLY_Brandur Ironhammer|r in Ironforge gives the same quest." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 48.43, y = 50.22, zone = "1453" },
        { "accept", quest = 8415, text = "Accept Chillwind Point" },
        { "target", name = "Lord Grayson Shadowbreaker" },
      },
      { only = "Dwarf Paladin", source = "polestar:forever/class/paladin/holy-mightstone",
        { "text", text = "|cOXP_FRIENDLY_Brandur Ironhammer|r" },
        { "text", text = "At 50 |cOXP_FRIENDLY_Brandur Ironhammer|r, the paladin trainer in the |cOXP_PICK_Mystic Ward|r, sends you to Chillwind Camp in the Western Plaguelands. |cOXP_FRIENDLY_Lord Grayson Shadowbreaker|r in Stormwind gives the same quest." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 23.13, y = 6.14, zone = "1455" },
        { "accept", quest = 8415, text = "Accept Chillwind Point" },
        { "target", name = "Brandur Ironhammer" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/holy-mightstone",
        { "text", text = "Chillwind Camp" },
        { "text", text = "Chillwind Camp is the Alliance camp at the south end of the Western Plaguelands, north of the Alterac foothills. |cOXP_FRIENDLY_Commander Ashlam Valorfist|r commands it; |cOXP_FRIENDLY_Argent Officer Pureheart|r stands in the same camp." },
        { "goto", x = 42.7, y = 84.03, zone = "1422" },
        { "turnin", quest = 8415, text = "Turn in Chillwind Point" },
        { "target", name = "Commander Ashlam Valorfist" },
        { "goto", x = 42.7, y = 84.03, zone = "1422" },
        { "accept", quest = 8414, text = "Accept Dispelling Evil" },
        { "target", name = "Commander Ashlam Valorfist" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/holy-mightstone", when = { { "has", item = 12846, n = 1, neg = true } },
        { "text", text = "The Argent Dawn Commission" },
        { "text", text = "The Scourge drop no Scourgestones unless you wear an Argent Dawn Commission. |cOXP_FRIENDLY_Argent Officer Pureheart|r gives you one through her quest, Argent Dawn Commission, which you hand in straight away (if you already have one from Light's Hope Chapel, wear that). Equip it in a trinket slot: it shows as a buff that never runs out. Keep it on until you have 20 stones." },
        { "goto", x = 42.97, y = 83.55, zone = "1422" },
        { "accept", quest = 5401, text = "Accept Argent Dawn Commission (|cOXP_FRIENDLY_Argent Officer Pureheart|r: Argent Dawn Commission)" },
        { "target", name = "Argent Officer Pureheart" },
        { "goto", x = 42.97, y = 83.55, zone = "1422" },
        { "turnin", quest = 5401, text = "Turn in Argent Dawn Commission (the Argent Dawn Commission trinket: equip it)" },
        { "target", name = "Argent Officer Pureheart" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/holy-mightstone",
        { "text", text = "Minion's Scourgestones" },
        { "text", text = "Kill the Scourge of the Western Plaguelands with the Commission on: skeletons, ghouls and cultists (level 50-58) drop a |cOXP_LOOT_Minion's Scourgestone|r about two kills in five. Sorrow Hill, just east of Chillwind Camp around Uther's Tomb, is the closest farm. Avoid the Flesh Golems that patrol the fields; Skeletal Guardians cast Cone of Cold and Arcane Explosion up close, Dark Summoners run for help at low health." },
        { "goto", x = 47.37, y = 84.3, zone = "1422" },
        { "complete", obj = 1, quest = 8414, text = "Minion's Scourgestone: 20 (|cOXP_LOOT_Minion's Scourgestone|r x20)" },
        { "mob", name = "Skeletal Flayer" },
        { "mob", name = "Skeletal Terror" },
        { "mob", name = "Skeletal Sorcerer" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/holy-mightstone",
        { "text", text = "|cOXP_FRIENDLY_High Priest Thel'danis|r" },
        { "text", text = "|cOXP_FRIENDLY_High Priest Thel'danis|r keeps watch at Uther's Tomb on Sorrow Hill, east of the camp. He turns your 20 stones into one |cOXP_LOOT_Inert Scourgestone|r: keep it." },
        { "goto", x = 52.05, y = 83.27, zone = "1422" },
        { "turnin", quest = 8414, text = "Turn in Dispelling Evil" },
        { "target", name = "High Priest Thel'danis" },
        { "goto", x = 52.05, y = 83.27, zone = "1422" },
        { "accept", quest = 8416, text = "Accept Inert Scourgestones" },
        { "target", name = "High Priest Thel'danis" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/holy-mightstone",
        { "text", text = "|cOXP_FRIENDLY_Commander Ashlam Valorfist|r" },
        { "text", text = "Back to Chillwind Camp. Ashlam needs the voodoo of the Sunken Temple's trolls for the stone." },
        { "goto", x = 42.7, y = 84.03, zone = "1422" },
        { "turnin", quest = 8416, text = "Turn in Inert Scourgestones" },
        { "target", name = "Commander Ashlam Valorfist" },
        { "goto", x = 42.7, y = 84.03, zone = "1422" },
        { "accept", quest = 8418, text = "Accept Forging the Mightstone" },
        { "target", name = "Commander Ashlam Valorfist" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/holy-mightstone",
        { "text", text = "The Sunken Temple" },
        { "text", text = "The Temple of Atal'Hakkar, the Sunken Temple, lies in the Pool of Tears in eastern Swamp of Sorrows: go up the ruin's stairs, dive into the flooded hall and follow the stairs down to the portal. It is a dungeon for a group of five at about 50-55. Six elite troll minibosses (level 51-52) stand on the balconies around the temple's great round room, each behind a pack of elites on its side path. Each drops its feather every time: Gasher and |cOXP_FRIENDLY_Zul'Lor|r the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green; you need all six. Hukku calls guardians and throws Shadow Bolt Volleys, Mijan heals: kill them first." },
        { "reach", text = "The Temple of Atal'Hakkar", x = 69.9, y = 53.6, zone = "1435" },
        { "goto", x = 69.9, y = 53.6, zone = "1435" },
        { "complete", obj = 1, quest = 8418, text = "Amber Voodoo Feather: 2 (|cOXP_LOOT_Amber Voodoo Feather|r x2: Gasher, |cOXP_FRIENDLY_Zul'Lor|r)" },
        { "goto", x = 69.9, y = 53.6, zone = "1435" },
        { "complete", obj = 2, quest = 8418, text = "Blue Voodoo Feather: 2 (|cOXP_LOOT_Blue Voodoo Feather|r x2: Hukku, Mijan)" },
        { "goto", x = 69.9, y = 53.6, zone = "1435" },
        { "complete", obj = 3, quest = 8418, text = "Green Voodoo Feather: 2 (|cOXP_LOOT_Green Voodoo Feather|r x2: Zolo, Loro)" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/holy-mightstone",
        { "text", text = "Forging the Mightstone" },
        { "text", text = "Back to Ashlam in Chillwind Camp: he forges the |cOXP_LOOT_Holy Mightstone|r. Look at the reward window before you hand in: Classic also offered the |cOXP_LOOT_Chivalrous Signet|r, the |cOXP_LOOT_Lightforged Blade|r or the |cOXP_LOOT_Sanctified Orb|r, and Forever's notes say that choice may be gone. Use the stone before a fight against undead (Stratholme, Scholomance): it lasts ten minutes and is gone after one use." },
        { "goto", x = 42.7, y = 84.03, zone = "1422" },
        { "turnin", quest = 8418, text = "Turn in Forging the Mightstone (|cOXP_FRIENDLY_Commander Ashlam Valorfist|r: |cOXP_LOOT_Holy Mightstone|r)" },
        { "target", name = "Commander Ashlam Valorfist" },
      },
      { only = "Priest", source = "polestar:forever/class/priest/blood-of-morphaz", when = { { "zone", name = "Ironforge" }, { "onquest", neg = true, quests = { 8254 } } },
        { "text", text = "Class quest: {quest:8257}" },
        { "text", text = "Cenarion Aid: |cOXP_FRIENDLY_High Priest Rohan|r" },
        { "text", text = "At 50 in Ironforge, |cOXP_FRIENDLY_High Priest Rohan|r in the |cOXP_PICK_Hall of Mysteries|r (|cOXP_PICK_Mystic Ward|r) offers Cenarion Aid. Before you leave a city, buy an |cOXP_LOOT_Ichor of Undeath|r at the Auction House (a few silver): the third quest asks for one and it drops rarely." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 24.73, y = 8.16, zone = "1455" },
        { "accept", quest = 8254, text = "Accept Cenarion Aid" },
        { "target", name = "High Priest Rohan" },
      },
      { only = "Priest", source = "polestar:forever/class/priest/blood-of-morphaz", when = { { "onquest", neg = true, quests = { 8254 } } },
        { "text", text = "Cenarion Aid: |cOXP_FRIENDLY_Brother Joshua|r" },
        { "text", text = "At 50, |cOXP_FRIENDLY_Brother Joshua|r at the altar of Stormwind's Cathedral of Light offers Cenarion Aid (|cOXP_FRIENDLY_High Priest Rohan|r in Ironforge has it too). Before you leave, buy an |cOXP_LOOT_Ichor of Undeath|r at the Auction House in the |cOXP_PICK_Trade District|r (a few silver): the third quest asks for one and it drops rarely." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 49.5, y = 45.21, zone = "1453" },
        { "accept", quest = 8254, text = "Accept Cenarion Aid" },
        { "target", name = "Brother Joshua" },
      },
      { only = "Priest", source = "polestar:forever/class/priest/blood-of-morphaz",
        { "text", text = "Cenarion Aid: |cOXP_FRIENDLY_Ur'kyo|r" },
        { "text", text = "At 50, |cOXP_FRIENDLY_Ur'kyo|r in Orgrimmar's |cOXP_PICK_Valley of Spirits|r offers Cenarion Aid. Before you leave, buy an |cOXP_LOOT_Ichor of Undeath|r at the Auction House (a few silver): the third quest asks for one and it drops rarely." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 35.59, y = 87.82, zone = "1454" },
        { "accept", quest = 8254, text = "Accept Cenarion Aid" },
        { "target", name = "Ur'kyo" },
      },
      { only = "Priest", source = "polestar:forever/class/priest/blood-of-morphaz",
        { "text", text = "|cOXP_FRIENDLY_Ogtinc|r" },
        { "text", text = "|cOXP_FRIENDLY_Ogtinc|r, a furbolg, lives on the clifftop north-east of the Ruins of Eldarath. Alliance: fly to Talrendis Point; Horde: fly to Valormok. Ride east and leave the road at the fork before the ruins, then follow the northern cliff edge east to him: the naga ruins and the beach below are walled in by cliffs with no way up." },
        { "goto", x = 11.9, y = 77.59, zone = "1447" },
        { "fp", name = "Talrendis Point", text = "Get the Talrendis Point flight path" },
        { "target", name = "Jarrodenus" },
        { "goto", x = 21.96, y = 49.62, zone = "1447" },
        { "fp", name = "Valormok", text = "Get the Valormok flight path" },
        { "target", name = "Kroum" },
        { "goto", x = 42.4, y = 42.62, zone = "1447" },
        { "turnin", quest = 8254, text = "Turn in Cenarion Aid" },
        { "target", name = "Ogtinc" },
        { "goto", x = 42.4, y = 42.62, zone = "1447" },
        { "accept", quest = 8255, text = "Accept Of Coursers We Know" },
        { "target", name = "Ogtinc" },
      },
      { only = "Priest", source = "polestar:forever/class/priest/blood-of-morphaz",
        { "text", text = "Of Coursers We Know" },
        { "text", text = "Mosshoof Coursers (level 52-53, not elite) graze all over Azshara, thickest north-east of |cOXP_FRIENDLY_Ogtinc|r and south of the mountains; about one in three drops a |cOXP_LOOT_Healthy Courser Gland|r, so plan on a dozen kills for four. They enrage at 30% health: finish them fast. Killing them costs no Cenarion Circle reputation. Keep any |cOXP_LOOT_Ichor of Undeath|r you loot." },
        { "goto", x = 52.1, y = 35.39, zone = "1447" },
        { "complete", obj = 1, quest = 8255, text = "Healthy Courser Gland: 4" },
        { "mob", name = "Mosshoof Courser" },
      },
      { only = "Priest", source = "polestar:forever/class/priest/blood-of-morphaz",
        { "text", text = "|cOXP_FRIENDLY_Ogtinc|r" },
        { "goto", x = 42.4, y = 42.62, zone = "1447" },
        { "turnin", quest = 8255, text = "Turn in Of Coursers We Know" },
        { "target", name = "Ogtinc" },
        { "goto", x = 42.4, y = 42.62, zone = "1447" },
        { "accept", quest = 8256, text = "Accept The Ichor of Undeath" },
        { "target", name = "Ogtinc" },
      },
      { only = "Priest", source = "polestar:forever/class/priest/blood-of-morphaz",
        { "text", text = "The Ichor of Undeath" },
        { "text", text = "Carrying an |cOXP_LOOT_Ichor of Undeath|r already? It counts at once. Otherwise any undead may drop one, rarely: the |cOXP_ENEMY_Lingering Highborne|r (level 48) in the Ruins of Eldarath below |cOXP_FRIENDLY_Ogtinc|r's cliff drop it about one kill in ten, the highborne ghosts on Azshara's border with Ashenvale (level 45-46) a little less, the Anguished and |cOXP_FRIENDLY_Suffering Highborne|r in Winterspring (54-55) about one in eight. The Auction House is usually quicker." },
        { "goto", x = 40.28, y = 46.13, zone = "1447" },
        { "complete", obj = 1, quest = 8256, text = "Ichor of Undeath: 1" },
        { "mob", name = "Lingering Highborne" },
        { "mob", name = "Highborne Apparition" },
        { "mob", name = "Highborne Lichling" },
      },
      { only = "Priest", source = "polestar:forever/class/priest/blood-of-morphaz",
        { "text", text = "|cOXP_FRIENDLY_Ogtinc|r" },
        { "goto", x = 42.4, y = 42.62, zone = "1447" },
        { "turnin", quest = 8256, text = "Turn in The Ichor of Undeath" },
        { "target", name = "Ogtinc" },
        { "goto", x = 42.4, y = 42.62, zone = "1447" },
        { "accept", quest = 8257, text = "Accept Blood of Morphaz" },
        { "target", name = "Ogtinc" },
      },
      { only = "Priest", source = "polestar:forever/class/priest/blood-of-morphaz",
        { "text", text = "Morphaz in the Sunken Temple" },
        { "text", text = "Morphaz is a level 52 elite green dragon inside the Sunken Temple, a five-player dungeon: bring a group of five (a level 60 group clears it with ease). Horde: fly to Stonard; Alliance: fly to Nethergarde Keep in the Blasted Lands and ride north. The temple stands in the middle of the Pool of Tears: climb the steps on its south side, swim down through the flooded hall and take the stairs to the portal. Inside, Morphaz only appears late: kill the six troll minibosses on the upper balconies, then |cOXP_FRIENDLY_Jammal'an the Prophet|r below them; that wakes the drakes Weaver and Dreamscythe in the Pit of Sacrifice, and killing both brings Morphaz and Hazzas. The pair patrols together and cannot be split: pull them into a hallway and have the tank face them away from the group (breath and a knockback). Loot him in a party, not a raid group: the blood always drops." },
        { "goto", x = 69, y = 54, zone = "1435" },
        { "complete", obj = 1, quest = 8257, text = "Blood of Morphaz: 1 (Blood of Morphaz: the Sunken Temple entrance)" },
      },
      { only = "Priest", source = "polestar:forever/class/priest/blood-of-morphaz",
        { "text", text = "|cOXP_FRIENDLY_Greta Mosshoof|r" },
        { "text", text = "|cOXP_FRIENDLY_Greta Mosshoof|r is at the Emerald Sanctuary in southern Felwood. Horde: fly to Bloodvenom Post and ride south-east; Alliance: fly to Astranaar in Ashenvale and ride north into Felwood. She takes the blood for experience and gold. Look at the reward window before you hand in: Classic let you pick |cOXP_LOOT_Blessed Prayer Beads|r, |cOXP_LOOT_Circle of Hope|r or Woestave, and Forever's notes say that choice may be gone." },
        { "goto", x = 51.21, y = 82.11, zone = "1448" },
        { "turnin", quest = 8257, text = "Turn in Blood of Morphaz" },
        { "target", name = "Greta Mosshoof" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/the-azure-key",
        { "text", text = "Class quest: {quest:8236}" },
        { "text", text = "A Simple Request (Alliance)" },
        { "text", text = "At 50 |cOXP_FRIENDLY_Osborne the Night Man|r in Stormwind's |cOXP_PICK_Old Town|r has it; so do Syurna in Darnassus and |cOXP_FRIENDLY_Hulfdan Blackbeard|r in Ironforge." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 77.43, y = 65.31, zone = "1453" },
        { "accept", quest = 8233, text = "Accept A Simple Request" },
        { "target", name = "Osborne the Night Man" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/the-azure-key",
        { "text", text = "A Simple Request (Horde)" },
        { "text", text = "At 50 |cOXP_FRIENDLY_Ormok|r in the |cOXP_PICK_Cleft of Shadow|r has it; so does |cOXP_FRIENDLY_Miles Dexter|r in the Undercity's |cOXP_PICK_Rogues' Quarter|r." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 43.9, y = 54.63, zone = "1454" },
        { "accept", quest = 8233, text = "Accept A Simple Request" },
        { "target", name = "Ormok" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/the-azure-key",
        { "text", text = "|cOXP_FRIENDLY_Lord Jorach Ravenholdt|r" },
        { "text", text = "Ravenholdt Manor hides in the hills east of Tarren Mill. Horde fly to Tarren Mill, Alliance to Southshore. The trail starts behind the plateau north of Durnholde Keep, climbs into the hills and runs through a small tunnel into the Alterac Mountains; Lord Jorach is inside the manor. Do not attack anyone at the manor: lost Ravenholdt reputation makes him refuse to speak to you." },
        { "goto", x = 86.02, y = 78.88, zone = "1416" },
        { "turnin", quest = 8233, text = "Turn in A Simple Request" },
        { "target", name = "Lord Jorach Ravenholdt" },
        { "goto", x = 86.02, y = 78.88, zone = "1416" },
        { "accept", quest = 8234, text = "Accept Sealed Azure Bag" },
        { "target", name = "Lord Jorach Ravenholdt" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/the-azure-key",
        { "text", text = "Sealed Azure Bag" },
        { "text", text = "Alliance fly to Talrendis Point, Horde to Valormok. Only the level 50-51 Timbermaw Shamans in the furbolg hills of northern Azshara carry the bag (the level 47-49 furbolgs further south do not): about one kill in thirty drops it. Pick Pocket them instead and you lose no Timbermaw reputation; if you are Unfriendly or better with Timbermaw Hold, mark them At War in your reputation panel first. They cast Lightning Bolt and Lightning Cloud, heal each other and run at low health." },
        { "goto", x = 11.9, y = 77.59, zone = "1447" },
        { "fp", name = "Talrendis Point", text = "Get the Talrendis Point flight path" },
        { "target", name = "Jarrodenus" },
        { "goto", x = 21.96, y = 49.62, zone = "1447" },
        { "fp", name = "Valormok", text = "Get the Valormok flight path" },
        { "target", name = "Kroum" },
        { "goto", x = 44.2, y = 26.6, zone = "1447" },
        { "complete", obj = 1, quest = 8234, text = "Sealed Azure Bag: 1 (Sealed Azure Bag: |cOXP_ENEMY_Timbermaw Shaman|r)" },
        { "mob", name = "Timbermaw Shaman" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/the-azure-key",
        { "text", text = "|cOXP_FRIENDLY_Archmage Xylem|r" },
        { "text", text = "|cOXP_FRIENDLY_Sanath Lim-yo|r, camped below the cliffs just east of Valormok, teleports you up (dismount first); a trail leads to Xylem's tower." },
        { "goto", x = 29.25, y = 40.21, zone = "1447" },
        { "turnin", quest = 8234, text = "Turn in Sealed Azure Bag" },
        { "target", name = "Archmage Xylem" },
        { "goto", x = 29.25, y = 40.21, zone = "1447" },
        { "accept", quest = 8235, text = "Accept Encoded Fragments" },
        { "target", name = "Archmage Xylem" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/the-azure-key",
        { "text", text = "Encoded Fragments" },
        { "text", text = "The Forest Oozes (level 52-53, Diseased Slime up close) drop a fragment four times in five: the biggest group, seven of them, is in the Bitter Reaches hills of north-eastern Azshara, four more south-east of Valormok. Pick their pockets before the kill for an extra fragment or two. Killing the Mistwing Ravagers and hippogryphs that share their spots makes more oozes appear." },
        { "goto", x = 36.16, y = 67.86, zone = "1447" },
        { "complete", obj = 1, quest = 8235, text = "Encoded Fragment: 10 (|cOXP_LOOT_Encoded Fragment|r: |cOXP_ENEMY_Forest Ooze|r)" },
        { "mob", name = "Forest Ooze" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/the-azure-key",
        { "text", text = "Back to Xylem" },
        { "goto", x = 29.25, y = 40.21, zone = "1447" },
        { "turnin", quest = 8235, text = "Turn in Encoded Fragments" },
        { "target", name = "Archmage Xylem" },
        { "goto", x = 29.25, y = 40.21, zone = "1447" },
        { "accept", quest = 8236, text = "Accept The Azure Key" },
        { "target", name = "Archmage Xylem" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/the-azure-key",
        { "text", text = "Morphaz in the Sunken Temple" },
        { "text", text = "Morphaz, a level 52 elite green drake, lives deep in the Sunken Temple: a group of five, level 50-54. The temple stands in the Pool of Tears; climb into the sunken building, swim down through it and follow the passage to the portal. Horde: fly to Stonard; Alliance: fly to Nethergarde Keep and ride on. He is not there when you arrive: first kill the six troll guardians (elites of 50-52) on the platforms around the upper ring, which opens the way down (the left-hand ramp from the entrance) to |cOXP_FRIENDLY_Jammal'an the Prophet|r in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe; when both are dead, Morphaz and Hazzas appear together and fight as a pair. Their Acid Breath is nature damage: nature protection potions help; poisons and Blind do not work on them. The key always drops. Hunters, Priests and Mages of 50 need Morphaz too: one clear serves them all." },
        { "goto", x = 69.9, y = 53.6, zone = "1435" },
        { "complete", obj = 1, quest = 8236, text = "Azure Key: 1 (|cOXP_LOOT_Azure Key|r: Morphaz, inside the temple)" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/the-azure-key",
        { "text", text = "Lord Ravenholdt" },
        { "text", text = "Look at the reward window before you hand in: Classic offered the |cOXP_LOOT_Duskbat Drape|r, the |cOXP_LOOT_Ebon Mask|r or the |cOXP_LOOT_Whisperwalk Boots|r, and Forever's notes say the choice may be gone." },
        { "goto", x = 86.02, y = 78.88, zone = "1416" },
        { "turnin", quest = 8236, text = "Turn in The Azure Key" },
        { "target", name = "Lord Jorach Ravenholdt" },
      },
      { only = "Human Warlock", source = "polestar:forever/class/warlock/impsys-request", when = { { "zone", name = "Felwood", neg = true } },
        { "text", text = "Class quest: {quest:8419}" },
        { "text", text = "An Imp's Request (Stormwind)" },
        { "text", text = "At 50 |cOXP_FRIENDLY_Demisette Cloyce|r in the |cOXP_PICK_Slaughtered Lamb|r, in the |cOXP_PICK_Mage Quarter|r, sends you to |cOXP_FRIENDLY_Impsy|r in Felwood with a piece of |cOXP_LOOT_Felcloth|r." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 39.24, y = 84.96, zone = "1453" },
        { "accept", quest = 8419, text = "Accept An Imp's Request" },
        { "target", name = "Demisette Cloyce" },
      },
      { only = "Gnome Warlock", source = "polestar:forever/class/warlock/impsys-request", when = { { "zone", name = "Felwood", neg = true } },
        { "text", text = "An Imp's Request (Ironforge)" },
        { "text", text = "At 50 |cOXP_FRIENDLY_Briarthorn|r in Ironforge sends you to |cOXP_FRIENDLY_Impsy|r in Felwood with a piece of |cOXP_LOOT_Felcloth|r." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 50.35, y = 5.66, zone = "1455" },
        { "accept", quest = 8419, text = "Accept An Imp's Request" },
        { "target", name = "Briarthorn" },
      },
      { only = "Orc Warlock/Troll Warlock", source = "polestar:forever/class/warlock/impsys-request", when = { { "zone", name = "Felwood", neg = true } },
        { "text", text = "An Imp's Request (Orgrimmar)" },
        { "text", text = "At 50 |cOXP_FRIENDLY_Zevrost|r in the |cOXP_PICK_Cleft of Shadow|r sends you to |cOXP_FRIENDLY_Impsy|r in Felwood with a piece of |cOXP_LOOT_Felcloth|r." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 48.47, y = 45.43, zone = "1454" },
        { "accept", quest = 8419, text = "Accept An Imp's Request" },
        { "target", name = "Zevrost" },
      },
      { only = "Scourge Warlock", source = "polestar:forever/class/warlock/impsys-request", when = { { "zone", name = "Felwood", neg = true } },
        { "text", text = "An Imp's Request (Undercity)" },
        { "text", text = "At 50 |cOXP_FRIENDLY_Kaal Soulreaper|r in the |cOXP_PICK_Magic Quarter|r sends you to |cOXP_FRIENDLY_Impsy|r in Felwood with a piece of |cOXP_LOOT_Felcloth|r." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 86.21, y = 15.93, zone = "1458" },
        { "accept", quest = 8419, text = "Accept An Imp's Request" },
        { "target", name = "Kaal Soulreaper" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/impsys-request",
        { "text", text = "|cOXP_LOOT_Felcloth|r" },
        { "text", text = "One |cOXP_LOOT_Felcloth|r: the Jadefire satyrs of Felwood drop it about one kill in fourteen, and so do the Legashi satyrs and the Felguard Sentries you hunt for Niby's essences. Quicker: buy one at the Auction House. You need it for the trainer's An Imp's Request or for |cOXP_FRIENDLY_Impsy|r's own Hot and Itchy, the same errand: whichever you hold." },
        { "goto", x = 32.23, y = 67.11, zone = "1448" },
        { "collect", count = 1, item = 14256, text = "Felcloth: 1" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/impsys-request", when = { { "onquest", quests = { 8419 } } },
        { "text", text = "|cOXP_FRIENDLY_Impsy|r" },
        { "text", text = "|cOXP_FRIENDLY_Impsy|r waits beside |cOXP_FRIENDLY_Niby the Almighty|r on a rise just north-east of Bloodvenom Post: coming north over the Bloodvenom Falls bridge, they stand off the road to the east, past a few oozes. Hand him the trainer's An Imp's Request with the cloth. Next he wants ten |cOXP_LOOT_Rotting Wood|r and four |cOXP_LOOT_Bloodvenom Essence|r." },
        { "goto", x = 41.36, y = 45.02, zone = "1448" },
        { "turnin", quest = 8419, text = "Turn in An Imp's Request" },
        { "target", name = "Impsy" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/impsys-request", when = { { "turnedin", neg = true, quest = 8419 } },
        { "text", text = "|cOXP_FRIENDLY_Impsy|r: Hot and Itchy" },
        { "text", text = "|cOXP_FRIENDLY_Impsy|r waits beside |cOXP_FRIENDLY_Niby the Almighty|r on a rise just north-east of Bloodvenom Post: coming north over the Bloodvenom Falls bridge, they stand off the road to the east, past a few oozes. Take his own Hot and Itchy and hand him the cloth at once. Next he wants ten |cOXP_LOOT_Rotting Wood|r and four |cOXP_LOOT_Bloodvenom Essence|r." },
        { "goto", x = 41.36, y = 45.02, zone = "1448" },
        { "accept", quest = 8420, text = "Accept Hot and Itchy (|cOXP_FRIENDLY_Impsy|r: Hot and Itchy)" },
        { "target", name = "Impsy" },
        { "goto", x = 41.36, y = 45.02, zone = "1448" },
        { "turnin", quest = 8420, text = "Turn in Hot and Itchy" },
        { "target", name = "Impsy" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/impsys-request",
        { "text", text = "|cOXP_LOOT_Rotting Wood|r and Bloodvenom" },
        { "text", text = "The Irontree treants (level 52) of Irontree Woods, in northern Felwood west of Talonbranch Glade, drop |cOXP_LOOT_Rotting Wood|r one time in four; the big |cOXP_ENEMY_Withered Protector|r (55) often drops three at once but hits hard and dazes. The Tainted Oozes (51) around |cOXP_FRIENDLY_Impsy|r and along the Bloodvenom drop the essence one time in five." },
        { "goto", x = 41.36, y = 45.02, zone = "1448" },
        { "accept", quest = 8421, text = "Accept The Wrong Stuff (|cOXP_FRIENDLY_Impsy|r: The Wrong Stuff)" },
        { "target", name = "Impsy" },
        { "goto", x = 48.51, y = 29.84, zone = "1448" },
        { "complete", obj = 1, quest = 8421, text = "Rotting Wood: 10" },
        { "mob", name = "Irontree Stomper" },
        { "mob", name = "Withered Protector" },
        { "mob", name = "Irontree Wanderer" },
        { "goto", x = 43.99, y = 46.35, zone = "1448" },
        { "complete", obj = 2, quest = 8421, text = "Bloodvenom Essence: 4" },
        { "mob", name = "Tainted Ooze" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/impsys-request",
        { "text", text = "|cOXP_FRIENDLY_Impsy|r again" },
        { "text", text = "|cOXP_FRIENDLY_Impsy|r now wants six |cOXP_LOOT_Voodoo Feathers|r from the Sunken Temple: a dungeon run." },
        { "goto", x = 41.36, y = 45.02, zone = "1448" },
        { "turnin", quest = 8421, text = "Turn in The Wrong Stuff" },
        { "target", name = "Impsy" },
        { "goto", x = 41.36, y = 45.02, zone = "1448" },
        { "accept", quest = 8422, text = "Accept Trolls of a Feather" },
        { "target", name = "Impsy" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/impsys-request",
        { "text", text = "The Sunken Temple" },
        { "text", text = "The Sunken Temple (Temple of Atal'Hakkar, level 50-56, a group of five) stands in the middle of the Pool of Tears: swim down into the temple and take the stairs to the entrance. The six troll guardians (level 51-52, elite) stand on the balconies around the central pit, each with adds; each drops his feather every time: Gasher and |cOXP_FRIENDLY_Zul'Lor|r the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Not soloable at 52." },
        { "goto", x = 69, y = 54, zone = "1435" },
        { "complete", obj = 1, quest = 8422, text = "Amber Voodoo Feather: 2 (Amber Voodoo Feathers: Gasher, |cOXP_FRIENDLY_Zul'Lor|r)" },
        { "goto", x = 69, y = 54, zone = "1435" },
        { "complete", obj = 2, quest = 8422, text = "Blue Voodoo Feather: 2 (Blue Voodoo Feathers: Hukku, Mijan)" },
        { "goto", x = 69, y = 54, zone = "1435" },
        { "complete", obj = 3, quest = 8422, text = "Green Voodoo Feather: 2 (Green Voodoo Feathers: Zolo, Loro)" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/impsys-request",
        { "text", text = "Trolls of a Feather" },
        { "text", text = "Choose the |cOXP_LOOT_Soul Harvester|r (staff), the |cOXP_LOOT_Abyss Shard|r (off-hand) or the |cOXP_LOOT_Robes of Servitude|r." },
        { "goto", x = 41.36, y = 45.02, zone = "1448" },
        { "turnin", quest = 8422, text = "Turn in Trolls of a Feather" },
        { "target", name = "Impsy" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/shard-of-the-green-flame",
        { "text", text = "Class quest: {item:18762}" },
        { "text", text = "|cOXP_FRIENDLY_Niby the Almighty|r" },
        { "text", text = "At 50 |cOXP_FRIENDLY_Niby the Almighty|r and his imp |cOXP_FRIENDLY_Impsy|r wait on a rise in central Felwood just north-east of Bloodvenom Post: coming north over the Bloodvenom Falls bridge, they stand off the road to the east, past a few oozes. |cOXP_FRIENDLY_Niby the Almighty|r sends you to |cOXP_FRIENDLY_Impsy|r, beside him, who wants three Flawless Fel Essences from three places." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 41.38, y = 44.85, zone = "1448" },
        { "accept", quest = 7601, text = "Accept What Niby Commands" },
        { "target", name = "Niby the Almighty" },
        { "goto", x = 41.36, y = 45.02, zone = "1448" },
        { "turnin", quest = 7601, text = "Turn in What Niby Commands" },
        { "target", name = "Impsy" },
        { "goto", x = 41.36, y = 45.02, zone = "1448" },
        { "accept", quest = 7602, text = "Accept Flawless Fel Essence" },
        { "target", name = "Impsy" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/shard-of-the-green-flame",
        { "text", text = "Azshara" },
        { "text", text = "The Legashi satyrs (level 51-53) hold the Legash Encampment on Azshara's northern coast. Every kind drops the essence three times in four; the satyrs burn mana and the Hellcallers rain fire, so pull them singly." },
        { "goto", x = 61.42, y = 20.92, zone = "1447" },
        { "complete", obj = 1, quest = 7602, text = "Flawless Fel Essence (Azshara): 1" },
        { "mob", name = "Legashi Satyr" },
        { "mob", name = "Legashi Rogue" },
        { "mob", name = "Legashi Hellcaller" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/shard-of-the-green-flame",
        { "text", text = "Jaedenar" },
        { "text", text = "Jaedenar lies just south of Bloodvenom Post, west of the road. The guide waits for level 53 first: its Legionnaires are 55. Of its two caves, Shadow Hold is the northern one, further up the hill; the other has no Legionnaires. Shadow Hold's tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward |cOXP_FRIENDLY_Lord Banehollow|r's chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of Jaedenar and Shadow Hold are all hostile." },
        { "xp", level = 53, text = "Reach level 53" },
        { "goto", x = 37.58, y = 50.21, zone = "1448" },
        { "complete", obj = 2, quest = 7602, text = "Flawless Fel Essence (Jaedenar): 1" },
        { "mob", name = "Jaedenar Legionnaire" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/shard-of-the-green-flame",
        { "text", text = "The Dark Portal" },
        { "text", text = "The Felguard Sentries (level 54) walk around the The Dark Portal in the south of the Blasted Lands, each with a felhunter. Leave the level 57 Servants of Razelikh alone: they cannot be killed without their own quest." },
        { "goto", x = 58.52, y = 51.23, zone = "1419" },
        { "complete", obj = 3, quest = 7602, text = "Flawless Fel Essence (Dark Portal): 1" },
        { "mob", name = "Felguard Sentry" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/shard-of-the-green-flame",
        { "text", text = "|cOXP_FRIENDLY_Impsy|r" },
        { "text", text = "Back to |cOXP_FRIENDLY_Impsy|r. He hands you the |cOXP_LOOT_Fel Fire|r: keep it, it wakes the infernal |cOXP_ENEMY_Kroshius|r." },
        { "goto", x = 41.36, y = 45.02, zone = "1448" },
        { "turnin", quest = 7602, text = "Turn in Flawless Fel Essence" },
        { "target", name = "Impsy" },
        { "goto", x = 41.36, y = 45.02, zone = "1448" },
        { "accept", quest = 7603, text = "Accept Kroshius' Infernal Core" },
        { "target", name = "Impsy" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/shard-of-the-green-flame",
        { "text", text = "|cOXP_ENEMY_Kroshius|r" },
        { "text", text = "|cOXP_ENEMY_Kroshius|r' remains lie in Shatter Scar Vale, the burnt crater north of |cOXP_FRIENDLY_Niby the Almighty|r: follow the road north from his camp; the remains lie a little east of it. Use the |cOXP_LOOT_Fel Fire|r beside them and wait for him to rise. |cOXP_ENEMY_Kroshius|r is elite (level 55): grouping up is encouraged; a warlock of 55 or more can solo him with Fear and damage over time, or with Enslave Demon, but fire spells do nothing to him and he knocks you back. If you die he heals to full; he rises again three minutes after he dies. An elite infernal patrols the pool south of the remains: pull |cOXP_ENEMY_Kroshius|r away from it. He always drops his core. Lost the |cOXP_LOOT_Fel Fire|r? Abandon the quest and take it again from |cOXP_FRIENDLY_Impsy|r." },
        { "goto", x = 45.7, y = 34.8, zone = "1448" },
        { "item", item = 18626, text = "Use Fel Fire (|cOXP_LOOT_Fel Fire|r, at |cOXP_PICK_Kroshius' Remains|r)" },
        { "goto", x = 45.7, y = 34.76, zone = "1448" },
        { "complete", obj = 1, quest = 7603, text = "Kill Kroshius: 1" },
        { "mob", name = "Kroshius" },
        { "goto", x = 45.7, y = 34.76, zone = "1448" },
        { "complete", obj = 2, quest = 7603, text = "Kroshius' Infernal Core: 1" },
        { "mob", name = "Kroshius" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/shard-of-the-green-flame",
        { "text", text = "Back to |cOXP_FRIENDLY_Niby the Almighty|r" },
        { "goto", x = 41.38, y = 44.85, zone = "1448" },
        { "turnin", quest = 7603, text = "Turn in Kroshius' Infernal Core (|cOXP_FRIENDLY_Niby the Almighty|r: |cOXP_LOOT_Shard of the Green Flame|r)" },
        { "target", name = "Niby the Almighty" },
      },
      { only = "Human Warrior/Skyborne Warrior", source = "polestar:forever/class/warrior/voodoo-feathers",
        { "text", text = "Class quest: {quest:8425}" },
        { "text", text = "A Troubled Spirit (Stormwind)" },
        { "text", text = "At 50, |cOXP_FRIENDLY_Wu Shen|r, beside |cOXP_FRIENDLY_Ilsa Corbin|r in the warrior trainers' building of |cOXP_PICK_Old Town|r, sends you to the |cOXP_FRIENDLY_Fallen Hero of the Horde|r in the Swamp of Sorrows." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 80.55, y = 59.87, zone = "1453" },
        { "accept", quest = 8417, text = "Accept A Troubled Spirit" },
        { "target", name = "Wu Shen" },
      },
      { only = "Dwarf Warrior/Gnome Warrior", source = "polestar:forever/class/warrior/voodoo-feathers",
        { "text", text = "A Troubled Spirit (Ironforge)" },
        { "text", text = "At 50, |cOXP_FRIENDLY_Kelv Sternhammer|r, the warrior trainer of Ironforge, sends you to the |cOXP_FRIENDLY_Fallen Hero of the Horde|r in the Swamp of Sorrows." },
