      { only = "Orc Warrior/Troll Warrior/Skyborne Warrior", source = "polestar:forever/class/warrior/voodoo-feathers",
        { "text", text = "A Troubled Spirit (Orgrimmar)" },
        { "text", text = "At 50, |cOXP_FRIENDLY_Sorek|r in the |cOXP_PICK_Valley of Honor|r sends you to the |cOXP_FRIENDLY_Fallen Hero of the Horde|r in the Swamp of Sorrows." },
