        { "text", text = "A Troubled Spirit (Undercity)" },
        { "text", text = "At 50, |cOXP_FRIENDLY_Christoph Walker|r, a warrior trainer of the Undercity, sends you to the |cOXP_FRIENDLY_Fallen Hero of the Horde|r in the Swamp of Sorrows." },
        { "xp", level = 50, text = "Reach level 50" },
        { "goto", x = 46.93, y = 15.23, zone = "1458" },
        { "accept", quest = 8417, text = "Accept A Troubled Spirit" },
        { "target", name = "Christoph Walker" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/voodoo-feathers",
        { "text", text = "The |cOXP_FRIENDLY_Fallen Hero of the Horde|r" },
        { "text", text = "The |cOXP_FRIENDLY_Fallen Hero of the Horde|r, a ghost, stands in the south-west of the Swamp of Sorrows, at the pass into the Blasted Lands, a short ride south-west of Stonard. Horde: fly to Stonard. Alliance: fly to Nethergarde Keep in the Blasted Lands and ride north through the pass. High-level beasts roam the way." },
        { "goto", x = 34.29, y = 66.14, zone = "1435" },
        { "turnin", quest = 8417, text = "Turn in A Troubled Spirit" },
        { "target", name = "Fallen Hero of the Horde" },
        { "goto", x = 34.29, y = 66.14, zone = "1435" },
        { "accept", quest = 8423, text = "Accept Warrior Kinship" },
        { "target", name = "Fallen Hero of the Horde" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/voodoo-feathers",
        { "text", text = "Helboars" },
